<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/CacheStore.php';use Core\CacheStore;use Core\DB;$opts=array('dry'=>false,'limit'=>0,'actors'=>6,'directors'=>3);$argv=isset($argv)?$argv:array();foreach(array_slice($argv,1)as $a){$a=(string)$a;if($a==='--dry'){$opts['dry']=true;}elseif(strpos($a,'--limit=')===0){$opts['limit']=max(0,(int)substr($a,8));}elseif(strpos($a,'--actors=')===0){$opts['actors']=max(0,(int)substr($a,9));}elseif(strpos($a,'--directors=')===0){$opts['directors']=max(0,(int)substr($a,12));}}try{$pdo=DB::pdo();$sql='SELECT id, genres, extra FROM media_items ORDER BY id ASC';if($opts['limit']>0){$sql.=' LIMIT '.(int)$opts['limit'];}$rows=$pdo->query($sql)->fetchAll();$upd=$pdo->prepare('UPDATE media_items SET genres=? WHERE id=?');$scan=0;$changed=0;$skipped=0;foreach($rows as $r){$scan++;$people=CacheStore::peopleTags((string)$r['extra'],$opts['directors'],$opts['actors']);if(!$people){$skipped++;continue;}$base=json_decode((string)$r['genres'],true);if(!is_array($base)){$base=array();}$merged=array_values(array_unique(array_merge($base,$people)));if(count($merged)===count($base)){$skipped++;continue;}if(!$opts['dry']){$upd->execute(array(json_encode($merged,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),(int)$r['id'],));}$changed++;}if(!$opts['dry']&&$changed>0){CacheStore::invalidateTagCaches();}printf("[%s] 扫描 %d 条｜写入 %d 条｜跳过 %d 条（无人物数据或已含人物标签）\n",$opts['dry']?'dry':'done',$scan,$changed,$skipped);if(!$opts['dry']&&$changed>0){echo"已推进标签缓存版本，首页标签云稍后自动包含演员/导演标签。\n";}exit(0);}catch(\Throwable $e){fwrite(STDERR,'回填失败：'.$e->getMessage()."\n");exit(1);}